def skill(robot):
    tray = "tray"
    for p in ["tray", "green tray"]:
        if robot.see(p):
            tray = p
            break
    for i in range(3):
        if robot.see("blue cube"):
            break
        top = robot.ask("Which object is on top of the blue cube? Answer with just its name, like red cube.")
        cand = top if "cube" in top else "red cube"
        if robot.pick(cand) or robot.pick("red cube"):
            robot.put_aside()
        else:
            break
    if not robot.see("blue cube"):
        return False
    if not robot.pick("blue cube"):
        return False
    if robot.place_on(tray):
        return True
    for p in ["tray", "green tray"]:
        if p != tray and robot.place_on(p):
            return True
    return False
